class SetakApp extends StatelessWidget {
  const SetakApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner:false, title:'ستاک تعمیرات', theme:ThemeData(useMaterial3:true,fontFamily:'sans',colorSchemeSeed:Colors.red), builder:(c,w)=>Directionality(textDirection:TextDirection.rtl,child:w!), home:const Root());
}

class Root extends StatefulWidget { const Root({super.key}); @override State<Root> createState()=>_RootState(); }
class _RootState extends State<Root> {
  final api=SetakApi(); bool checking=true; bool logged=false;
  @override void initState(){super.initState(); _check();}
  Future<void> _check() async { try { await api.me(); logged=true; } catch(_){ logged=false; } if(mounted)setState(()=>checking=false); }
  @override Widget build(BuildContext context){ if(checking)return const Scaffold(body:Center(child:CircularProgressIndicator())); return logged?Home(api:api,onLogout:(){setState(()=>logged=false);}):Login(api:api,onLogin:(){setState(()=>logged=true);}); }
}

class Login extends StatefulWidget { final SetakApi api; final VoidCallback onLogin; const Login({super.key,required this.api,required this.onLogin}); @override State<Login> createState()=>_LoginState(); }
class _LoginState extends State<Login>{final url=TextEditingController();final user=TextEditingController();final pass=TextEditingController();bool busy=false;String? error;
